PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE maps (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  seed TEXT NOT NULL,
  generator_version INTEGER NOT NULL,
  map_hash TEXT NOT NULL UNIQUE,
  map_json TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('approved', 'rejected')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, player_count INTEGER NOT NULL DEFAULT 2);
CREATE TABLE player_maps (
  player_id TEXT NOT NULL,
  map_id INTEGER NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (player_id, map_id),

  FOREIGN KEY (map_id)
    REFERENCES maps(id)
    ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_maps_status
ON maps(status);
CREATE INDEX idx_maps_seed
ON maps(seed);
CREATE INDEX idx_player_maps_player
ON player_maps(player_id);
CREATE INDEX idx_player_maps_map
ON player_maps(map_id);
CREATE INDEX idx_maps_status_player_count
  ON maps(status, player_count);
